    }
};

// 1. Preordine (Rădăcină - Stânga - Dreapta)
void preordine(Nod* radacina) {
    if (radacina == nullptr) return;
    
    cout << radacina->valoare << " "; // R
    preordine(radacina->stanga);      // S
    preordine(radacina->dreapta);     // D
}

// 2. Inordine (Stânga - Rădăcină - Dreapta)
