    cout << radacina->valoare << " "; // R
    inordine(radacina->dreapta);      // D
}

// 3. Postordine (Stânga - Dreapta - Rădăcină)
void postordine(Nod* radacina) {
    if (radacina == nullptr) return;
    
    postordine(radacina->stanga);     // S
    postordine(radacina->dreapta);    // D
    cout << radacina->valoare << " "; // R
}

